def clean(df):
    df = df.copy()
    # Fix body_mass_g out-of-range values (likely entered in mg instead of g)
    df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] = df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] / 1000.0
    return df

def answer(df):
    df = clean(df)
    g = df.groupby('species')['body_mass_g'].mean()
    return {k: v for k, v in g.items()}
